#!/usr/bin/env node
const fs = require('fs-extra');
const path = require('path');

var outputDefinePath = ".vscode/robloxLibs/_gen"
var outputRobloxManifest = "build/_robloxManifest"


var writeRojoConfigs = require('./write-rojo-configs');
var writeLuaTypes = require('./write-lua-types');
var writeLuaTangSengFacade = require('./write-lua-tangsengFacade');
var writeLuaDefinesTangsengFacade = require('./write-lua-defines-tangsengFacade');
var writeLuaEvents = require('./write-lua-events');
var writeLuaInterface = require('./write-lua-interfaces');
var writeLuaProtos = require('./write-lua-protos');
var writeServiceCollectionExtensions = require('./write-service-collection-extensions');
var writeLuaSystems = require('./write-lua-systems');



var parseSystems = require('./parse-systems');
var parseServices = require('./parse-services');
var parseConfigs = require('./parse-configs');
var parseEvents = require('./parse-events');
var parseInterfaces = require('./parse-interfaces');
var parseProtos = require('./parse-protos');
const { exit } = require('process');

// rojo template path
var [rojoTemplatePath, rojoConfigPath] = process.argv.slice(2);
rojoTemplatePath = rojoTemplatePath ? rojoTemplatePath : "default.rojo-template.project.json"
rojoConfigPath = rojoConfigPath ? rojoConfigPath : "default.project.json"

// system root
var systemRoot = process.argv[4] ? process.argv[4] : "src/Systems"
systemRoot = systemRoot.replace(/\\/g, '/');

// packages folder
var folders = process.argv.slice(5)

var packageFolders = []
var ignoreFolders = []

// 分类处理 folders 中的路径
folders.forEach(folder => {
    if (folder.startsWith('!')) {
        ignoreFolders.push(path.resolve(folder.substring(1)))
    } else {
        packageFolders.push(folder)
    }
})

packageFolders.push(systemRoot)


// 是否忽略路径
function isIgnoreFolder(folder) {
    return ignoreFolders.some(ignoreFolder => folder.startsWith(ignoreFolder))
}


var options = {
    robloxPathDict: undefined,
    systemRoot: systemRoot,
    packageFolders: packageFolders,
    isIgnoreFolder: isIgnoreFolder,
    parseSystems: parseSystems,
}

// 此时还没有rojo配置，先生成
parseSystems.Init(options)
parseSystems.TryGen(packageFolders)
writeRojoConfigs(rojoTemplatePath, rojoConfigPath, parseSystems, systemRoot)


var robloxPathDict = require('./get-rojo-path');
robloxPathDict.init(rojoConfigPath)

// 额外监听文件夹
packageFolders.push("build/_robloxManifest/Extensions")

// watch main folders
var watcher = require('./watcher');
watcher.watchFiles(packageFolders);


// watch rojo template
var rojoWatcher = require('./watcher-rojo');
rojoWatcher.watchFiles([rojoTemplatePath]);

var ignoreFiles = ["EventsHelper.lua"]



function writeFiles() {
    writeRojoConfigs(rojoTemplatePath, rojoConfigPath, parseSystems, systemRoot)
    writeLuaSystems(parseSystems.GetSystems(), outputRobloxManifest)
    writeLuaTypes(parseServices.GetLuaTypes(), outputRobloxManifest)
    writeLuaDefinesTangsengFacade({}, outputDefinePath)
    writeLuaEvents(parseEvents.GetLuaEvents(), outputRobloxManifest)
    writeLuaTangSengFacade(parseInterfaces.GetLuaInterfaces(), outputRobloxManifest)
    writeLuaInterface(parseInterfaces.GetLuaInterfaces(), outputDefinePath)
    writeLuaProtos(parseProtos.GetLuaProtos(), outputDefinePath, outputRobloxManifest)
    writeServiceCollectionExtensions(parseServices.GetServiceCollectionExtensions(), outputRobloxManifest)
}

options.robloxPathDict = robloxPathDict


function init() {
    parseSystems.Init(options)
    parseSystems.TryGen(packageFolders)

    parseServices.Init(options)
    parseServices.TryGen(packageFolders);

    parseConfigs.Init(options)
    parseConfigs.TryGen(packageFolders);


    parseEvents.Init(options)
    parseEvents.TryGen(packageFolders)

    parseInterfaces.Init(options)
    parseInterfaces.TryGen(packageFolders)

    parseProtos.Init(options)
    parseProtos.TryGen(packageFolders)

    writeFiles()
}

var states = {}
var curKey = 0

function onWatchUpdate(events) {
    curKey = 0
    // 从 ignorePaths 中排除 events
    // 从 events 中过滤掉 ignoreFiles 中的文件
    events = Object.keys(events).reduce((filteredEvents, eventPath) => {
        if (!ignoreFiles.some(ignoreFile => eventPath.endsWith(ignoreFile))) {
            filteredEvents[eventPath] = events[eventPath];
        }
        return filteredEvents;
    }, {});


    if (parseInterfaces.TryGenOnUpdate(events)) {
        writeLuaInterface(parseInterfaces.GetLuaInterfaces(), outputDefinePath)
        curKey++
    }

    // 从 events 中，过滤掉其路径包含 "Extensions" 的文件
    events = Object.keys(events).reduce((filteredEvents, eventPath) => {
        if (!eventPath.includes("build\\_robloxManifest\\Extensions")) {
            filteredEvents[eventPath] = events[eventPath];
        }
        return filteredEvents;
    }, {});

    if (parseSystems.TryGenOnUpdate(events)) {
        writeFiles()
        writeLuaSystems(parseSystems.GetSystems(), outputRobloxManifest)
    }

    if (parseServices.TryGenOnUpdate(events)) {
        writeServiceCollectionExtensions(parseServices.GetServiceCollectionExtensions(), outputRobloxManifest)
        writeLuaTypes(parseServices.GetLuaTypes(), outputRobloxManifest)
        writeLuaDefinesTangsengFacade({}, outputDefinePath)
        writeLuaTangSengFacade(parseInterfaces.GetLuaInterfaces(), outputRobloxManifest)
        curKey++
    }


    if (parseEvents.TryGenOnUpdate(events)) {
        writeLuaEvents(parseEvents.GetLuaEvents(), outputRobloxManifest)
        curKey++
    }


    if (parseProtos.TryGenOnUpdate(events)) {
        writeLuaProtos(parseProtos.GetLuaProtos(), outputDefinePath, outputRobloxManifest)
        curKey++
    }
}


function wrapWatchUpdate(events, handler) {
    try {
        handler(events)
        // print if all in states is true
        if (Object.values(states).every(state => state)) {
            console.log("success write files")
        }
    } catch (e) {
        states[curKey] = false
        console.error("TangSeng Error:" + e.message)
        throw (e)
    }
}




watcher.registerEventCallback(function (events) {
    wrapWatchUpdate(events, onWatchUpdate)
});

rojoWatcher.registerEventCallback(function (events) {
    onWatchUpdate(events, function () {
        writeRojoConfigs(rojoTemplatePath, rojoConfigPath, parseSystems, systemRoot)
    })
});

try {
    init()
    console.log("success write files")
} catch (e) {
    throw e
    console.error("TangSeng Error:" + e.message)
    exit(0)
}